//! Tests of the arithmetic functions: against their definitions for small numbers, against PARI
//! for long ones (from their factorisations), on both byte orders and non-canonical numbers.

use a::math::numbers::{ByteOrder, Factorization, Number};

fn n(x: i64) -> Number {
    Number::new_from_i64(x, ByteOrder::BigEndian)
}

fn int(x: &Number) -> u128 {
    u128::try_from(x).unwrap()
}

fn gcd(a: u64, b: u64) -> u64 {
    if b == 0 { a } else { gcd(b, a % b) }
}

/// The factorisation of `m >= 1` by trial division, in the byte order `order`: the tests' own,
/// quicker under Miri than [`Number::factor`].
fn factorise(mut m: u64, order: ByteOrder) -> Factorization {
    let mut f = Vec::new();
    let mut p = 2;
    while p * p <= m {
        let mut e = 0;
        while m.is_multiple_of(p) {
            m /= p;
            e += 1;
        }
        if e > 0 {
            f.push((Number::new_from_u64(p, order), e));
        }
        p += 1;
    }
    if m > 1 {
        f.push((Number::new_from_u64(m, order), 1));
    }
    Factorization::new(f, order)
}

/// The same number in the other byte order, with zero bytes above its top.
fn other(x: &Number) -> Number {
    let mut v = x.value.clone();
    v.reverse();
    let order = match x.byte_order {
        ByteOrder::BigEndian => ByteOrder::LittleEndian,
        ByteOrder::LittleEndian => ByteOrder::BigEndian,
    };
    match order {
        ByteOrder::BigEndian => v.insert(0, 0),
        ByteOrder::LittleEndian => v.push(0),
    }
    Number {
        value: v,
        negative: x.negative,
        byte_order: order,
    }
}

/// The definitions, for `m >= 1`: divisors, `σ_k`, `φ`, `λ` (the least exponent that takes every
/// unit to 1), `μ`, square-freeness, radical.
struct Reference {
    divisors: Vec<u64>,
    sigma: [u128; 4],
    phi: u64,
    lambda: u64,
    mu: i32,
    squarefree: bool,
    radical: u64,
}

fn reference(m: u64) -> Reference {
    let divisors: Vec<u64> = (1..=m).filter(|d| m.is_multiple_of(*d)).collect();
    let mut sigma = [0u128; 4];
    for (k, s) in sigma.iter_mut().enumerate() {
        *s = divisors.iter().map(|&d| u128::from(d).pow(k as u32)).sum();
    }
    let units: Vec<u64> = (1..=m).filter(|&a| gcd(a, m) == 1).collect();
    let phi = units.len() as u64;
    let lambda = (1..=m.max(1))
        .find(|&e| {
            units.iter().all(|&a| {
                let mut x = 1u64 % m;
                for _ in 0..e {
                    x = x * a % m;
                }
                x == 1 % m
            })
        })
        .unwrap();
    let mut x = m;
    let mut p = 2;
    let mut radical = 1;
    let mut mu = 1;
    let mut squarefree = true;
    while x > 1 {
        if x.is_multiple_of(p) {
            radical *= p;
            mu = -mu;
            x /= p;
            if x.is_multiple_of(p) {
                squarefree = false;
                mu = 0;
                while x.is_multiple_of(p) {
                    x /= p;
                }
            }
        }
        p += 1;
    }
    Reference {
        divisors,
        sigma,
        phi,
        lambda,
        mu,
        squarefree,
        radical,
    }
}

#[test]
fn arithmetic_functions_against_their_definitions() {
    let limit = if cfg!(miri) { 10 } else { 700 };
    for m in 1..limit {
        let r = reference(m);
        let forms = [
            n(m as i64),
            n(-(m as i64)),
            Number::new_from_u64(m, ByteOrder::LittleEndian),
        ];
        let forms: Vec<Number> = if cfg!(miri) {
            vec![forms[0].clone(), other(&forms[1])]
        } else {
            forms.iter().flat_map(|x| [other(x), x.clone()]).collect()
        };
        {
            for x in forms {
                let d: Vec<u64> = x.divisors().iter().map(|d| int(d) as u64).collect();
                assert_eq!(d, r.divisors, "divisors of {m}");
                assert_eq!(int(&x.divisor_count()), r.divisors.len() as u128, "d({m})");
                for k in 0..4 {
                    assert_eq!(int(&x.divisor_sigma(k)), r.sigma[k as usize], "σ_{k}({m})");
                }
                assert_eq!(int(&x.totient()), u128::from(r.phi), "φ({m})");
                assert_eq!(int(&x.carmichael()), u128::from(r.lambda), "λ({m})");
                assert_eq!(x.mobius(), r.mu, "μ({m})");
                assert_eq!(x.is_squarefree(), r.squarefree, "{m} square-free");
                assert_eq!(int(&x.radical()), u128::from(r.radical), "rad({m})");
                // From the factorisation too.
                let f = factorise(m, x.byte_order);
                assert_eq!(f.divisors(), x.divisors());
                assert_eq!(f.totient(), x.totient());
                assert_eq!(f.carmichael(), x.carmichael());
                assert_eq!(f.divisor_sigma(2), x.divisor_sigma(2));
                assert_eq!(f.mobius(), r.mu);
                assert_eq!(f.radical(), x.radical());
            }
        }
    }
}

#[test]
fn results_in_the_byte_order_of_the_operand() {
    for order in [ByteOrder::BigEndian, ByteOrder::LittleEndian] {
        let x = Number::new_from_u64(720, order);
        assert!(x.divisors().iter().all(|d| d.byte_order == order));
        for y in [
            x.divisor_count(),
            x.divisor_sigma(3),
            x.totient(),
            x.carmichael(),
            x.radical(),
        ] {
            assert_eq!(y.byte_order, order);
        }
        // Beyond 2^64, by `factor`, too slow under Miri.
        if !cfg!(miri) {
            let big = (Number::new_from_u64(1, order) << 70usize) * 3u8;
            for y in [
                big.divisor_count(),
                big.divisor_sigma(1),
                big.totient(),
                big.carmichael(),
                big.radical(),
            ] {
                assert_eq!(y.byte_order, order);
            }
        }
        let f = Factorization::new(vec![(n(2), 3), (n(3), 1)], order);
        assert!(f.divisors().iter().all(|d| d.byte_order == order));
        assert_eq!(f.totient().byte_order, order);
    }
}

#[test]
fn zero() {
    assert!(!n(0).is_squarefree());
    let negative_zero = Number {
        value: vec![0, 0],
        negative: true,
        byte_order: ByteOrder::LittleEndian,
    };
    assert!(!negative_zero.is_squarefree());
    // The factorisation of 1.
    let one = Factorization::new(Vec::new(), ByteOrder::BigEndian);
    assert_eq!(one.divisors(), [n(1)]);
    assert_eq!(one.divisor_count(), n(1));
    assert_eq!(one.divisor_sigma(5), n(1));
    assert_eq!(one.totient(), n(1));
    assert_eq!(one.carmichael(), n(1));
    assert_eq!(one.mobius(), 1);
    assert!(one.is_squarefree());
    assert_eq!(one.radical(), n(1));
}

#[test]
#[should_panic(expected = "zero has no factorisation")]
fn totient_of_zero() {
    n(0).totient();
}

#[test]
#[should_panic(expected = "zero has no factorisation")]
fn divisors_of_zero() {
    Number {
        value: Vec::new(),
        negative: false,
        byte_order: ByteOrder::BigEndian,
    }
    .divisors();
}

#[test]
#[should_panic(expected = "zero has no factorisation")]
fn mobius_of_zero() {
    n(0).mobius();
}

