/// A factorisation `p^e * q^f ...` as text.
fn factorisation(text: &str, order: ByteOrder) -> Factorization {
    let f = text
        .split('*')
        .map(|t| {
            let (p, e) = t.split_once('^').unwrap_or((t, "1"));
            (
                Number::from_str_radix(p.trim(), 10, order).unwrap(),
                e.trim().parse().unwrap(),
            )
        })
        .collect();
    Factorization::new(f, order)
}

#[test]
fn long_numbers_against_pari() {
    let cases = if cfg!(miri) { &PARI[..1] } else { PARI };
    for &(f, d, s1, s2, phi, lambda, mu, rad) in cases {
        for order in [ByteOrder::BigEndian, ByteOrder::LittleEndian] {
            let f = factorisation(f, order);
            let num = |s: &str| Number::from_str_radix(s, 10, order).unwrap();
            assert_eq!(f.divisor_count(), num(d));
            assert_eq!(f.divisor_sigma(1), num(s1));
            assert_eq!(f.divisor_sigma(2), num(s2));
            assert_eq!(f.totient(), num(phi));
            assert_eq!(f.carmichael(), num(lambda));
            assert_eq!(f.mobius(), mu);
            assert_eq!(f.is_squarefree(), mu != 0);
            assert_eq!(f.radical(), num(rad));
        }
    }
}

#[test]
fn divisors_of_long_numbers() {
    // 2^100 3^2 5 (7^20 13): increasing, each divides, and as many as d(n).
    let f = if cfg!(miri) {
        Factorization::new(vec![(n(2), 70), (n(3), 1)], ByteOrder::LittleEndian)
    } else {
        Factorization::new(
            vec![(n(2), 100), (n(3), 2), (n(5), 1), (n(7), 20), (n(13), 1)],
            ByteOrder::LittleEndian,
        )
    };
    let v = f.value();
    let d = f.divisors();
    assert_eq!(
        Number::new_from_usize(d.len(), ByteOrder::BigEndian),
        f.divisor_count()
    );
    assert!(d.windows(2).all(|w| w[0] < w[1]));
    assert!(d.iter().all(|x| v.rem_euclid(x).is_zero()));
    assert_eq!(d[0], n(1));
    assert_eq!(*d.last().unwrap(), v);
    // Below 2^128, in pairs of words.
    let (e2, e3) = if cfg!(miri) { (10, 3) } else { (60, 20) };
    let f = Factorization::new(
        vec![(n(2), e2), (n(3), e3), (n(1_000_003), 1)],
        ByteOrder::BigEndian,
    );
    let d = f.divisors();
    assert_eq!(d.len(), (e2 as usize + 1) * (e3 as usize + 1) * 2);
    assert!(d.windows(2).all(|w| w[0] < w[1]));
    // A long prime.
    let p = (n(1) << 127usize) - 1u8;
    let f = Factorization::new(vec![(p.clone(), 2)], ByteOrder::BigEndian);
    assert_eq!(f.divisors(), [n(1), p.clone(), &p * &p]);
    assert_eq!(f.divisor_sigma(1), n(1) + &p + &p * &p);
    assert_eq!(f.totient(), &(&p - 1u8) * &p);
    assert_eq!(f.carmichael(), &(&p - 1u8) * &p);
    // Many primes: d(n) passes 2^128 for 130 primes.
    let primes: Vec<(Number, u32)> = (2u64..)
        .filter(|&q| (2..q).take_while(|d| d * d <= q).all(|d| q % d != 0))
        .take(130)
        .map(|q| (Number::new_from_u64(q, ByteOrder::BigEndian), 1))
        .collect();
    let f = Factorization::new(primes, ByteOrder::BigEndian);
    assert_eq!(f.divisor_count(), n(1) << 130usize);
    assert_eq!(f.mobius(), 1);
    // σ_k by the closed form for long exponents.
    let f = Factorization::new(vec![(n(3), 40)], ByteOrder::BigEndian);
    let want: Number = (0..=40u32).map(|i| n(3).pow(3 * i)).sum();
    assert_eq!(f.divisor_sigma(3), want);
}
